def signal(obs):
    a = obs.last('A','mid'); ax = obs.last('A.X','mid')
    b = obs.last('B','mid')
    c = obs.last('C','mid')
    idx = obs.last('IDX','mid')
    if a is None or b is None or c is None or idx is None:
        return {}
    # check nan
    if a!=a or b!=b or c!=c or idx!=idx:
        return {}
    basket = 0.3333*a + 0.6667*b + 0.1667*c
    spread = idx - basket
    s = obs.state
    if 'spreads' not in s:
        s['spreads']= []
    s['spreads'].append(spread)
    if len(s['spreads'])>100:
        s['spreads']=s['spreads'][-100:]
    if len(s['spreads'])<30:
        return {}
    arr = np.array(s['spreads'])
    m = float(np.nanmean(arr))
    sd = float(np.nanstd(arr))
    if sd<1e-6 or sd!=sd:
        return {}
    z = (spread - m)/sd
    zc = max(-1,min(1, -z/2))
    totW = 0.3333+0.6667+0.1667
    pos={}
    pos['IDX']= zc
    pos['A']= -zc * 0.3333/totW * 1.2
    pos['B']= -zc * 0.6667/totW * 1.2
    pos['C']= -zc * 0.1667/totW * 1.2
    for asset in ['A','B','C','IDX']:
        imb = obs.last(asset,'imbalance')
        if imb is not None and imb==imb:
            tilt = max(-0.3,min(0.3, imb*0.5))
            if asset in pos:
                pos[asset] = max(-1,min(1, pos[asset]+tilt*0.3))
            else:
                pos[asset]=tilt*0.3
    pos['A.X']=0; pos['B.X']=0; pos['C.X']=0
    return pos

