def signal(obs):
    s=obs.state
    if 't' not in s:
        s['t']=0
        s['pos']=0
    s['t']+=1
    # only act every 5 signals = 50 steps
    if s['t'] % 5 != 0:
        return {}
    c = obs.hist('C','mid',60)
    if c is None or len(c)<60:
        return {}
    if np.isnan(c).any():
        return {}
    past30 = c[-1] - c[-30]
    past50 = c[-1] - c[-50]
    # combined signal
    sig = 0.6*past30 + 0.4*past50
    # threshold to avoid noise: 5 cents ~ 1 std of 30step
    thr = 6.0
    target = 0
    if sig > thr:
        target = 0.8
    elif sig < -thr:
        target = -0.8
    else:
        target = s['pos']*0.7  # slowly decay to reduce turnover
        if abs(target)<0.15:
            target=0
    s['pos']=target
    # hedge venues: keep X flat
    return {'C': target, 'C.X': 0, 'A':0, 'A.X':0, 'B':0, 'B.X':0, 'IDX':0}

