def signal(obs):
    # Try dual venue arbitrage but with state to avoid thrashing
    # Actually earlier analysis showed prem mean 0.3 and std 2.6 but breach never after fees.
    # So skip cross-venue for now.
    # Try pure imbalance strategy on A.X (strongest)
    try:
        # Use A.X imbalance to trade A.X? but fee heavy.
        # Instead trade A (no fee) using A imbalance, plus A.X signal?
        imA = obs.last('A','imbalance')
        imAX = obs.last('A.X','imbalance')
        # combine?
        if math.isnan(imA) and math.isnan(imAX):
            return {}
        # weighted avg: A.X had 0.31 correlation, A 0.13, but AX more predictive
        # But trading on primary venue A which has 0 fee may be better.
        sig = 0
        cnt=0
        if not math.isnan(imA):
            sig+=imA
            cnt+=1
        if not math.isnan(imAX):
            sig+=imAX*0.5  # weight less?
            cnt+=1
        if cnt>0:
            sig/=cnt
        # threshold
        thresh=0.4
        target={}
        if sig>thresh:
            target['A']=1.0
        elif sig<-thresh:
            target['A']=-1.0
        else:
            target['A']=0.0
        # Also try similar for C momentum? We'll add later.
        return target
    except:
        return {}

def signal(obs):
    s = obs.state
    if 'pc' not in s:
        s['pc'] = 0
        s['pb'] = 0
    try:
        mC = obs.hist('C','mid', 40)
        if len(mC) >= 35:
            cur = mC[-1]
            prev = mC[-31]
            if not np.isnan(cur) and not np.isnan(prev):
                r = cur - prev
                if r > 7:
                    s['pc'] = 1
                elif r < -7:
                    s['pc'] = -1
                elif abs(r) < 2:
                    s['pc'] = 0
        mB = obs.hist('B','mid', 40)
        if len(mB) >= 35:
            cur = mB[-1]
            prev = mB[-31]
            if not np.isnan(cur) and not np.isnan(prev):
                r = cur - prev
                if r > 4:
                    s['pb'] = 1
                elif r < -4:
                    s['pb'] = -1
                elif abs(r) < 1:
                    s['pb'] = 0
        out = {}
        out['C'] = float(s['pc']) * 0.8
        out['B'] = float(s['pb']) * 0.6
        out['A'] = 0.0
        out['IDX'] = 0.0
        return out
    except:
        return {}

