res = {}
for k in ['A','B','C']:
    kx = k+'.X'
    bid = H[k]['bid']; ask = H[k]['ask']
    bidx = H[kx]['bid']; askx = H[kx]['ask']
    # buy on X sell on primary: bid - askx ; need fee 3bps on X leg? fee ~ 3bps * price
    p_buyx = bid - askx
    p_buy = bidx - ask
    def st(x):
        x = x[x==x]
        return {'mean': float(np.mean(x)), 'max': float(np.max(x)), 'frac_pos': float(np.mean(x>0))}
    res[k] = {'buyX_sellPrimary': st(p_buyx), 'buyPrimary_sellX': st(p_buy)}
result = res

def signal(obs):
    st = obs.state
    prev = st.get('p', {})
    out = {}
    # index vs basket hedge tilt
    try:
        ia = obs.last('A', 'mid'); ib = obs.last('B', 'mid')
        ic = obs.last('C', 'mid'); ix = obs.last('IDX', 'mid')
        if ia == ia and ib == ib and ic == ic and ix == ix:
            bask = 0.3333 * ia + 0.6667 * ib + 0.1667 * ic
            diff = ix - bask
        else:
            diff = 0.0
    except Exception:
        diff = 0.0
    if diff != diff:
        diff = 0.0
    # scale: typical std ~7
    arb = diff / 7.0
    if arb > 2.0:
        arb = 2.0
    if arb < -2.0:
        arb = -2.0
    for k in ('A', 'B', 'C', 'IDX'):
        try:
            m = obs.hist(k, 'mid', 130)
            n = len(m)
            if n < 70:
                raw = 0.0
            else:
                now = m[n-1]
                old = m[n-61]
                if now != now or old != old:
                    raw = 0.0
                else:
                    mom = now - old
                    # vol: mean abs step change over window
                    s = 0.0
                    c = 0
                    for i in range(n-60, n):
                        d = m[i] - m[i-1]
                        if d == d:
                            s += abs(d)
                            c += 1
                    vol = s / c if c > 0 and s > 0 else 1.0
                    z = mom / (vol * 7.746)
                    # own imbalance
                    try:
                        im = obs.hist(k, 'imbalance', 10)
                        si = 0.0; ci = 0
                        for v in im:
                            if v == v:
                                si += v; ci += 1
                        imb = si / ci if ci > 0 else 0.0
                    except Exception:
                        imb = 0.0
                    # cross-venue imbalance for primaries
                    imx = 0.0
                    if k in ('A', 'B', 'C'):
                        try:
                            im2 = obs.hist(k + '.X', 'imbalance', 10)
                            s2 = 0.0; c2 = 0
                            for v in im2:
                                if v == v:
                                    s2 += v; c2 += 1
                            if c2 > 0:
                                imx = s2 / c2
                        except Exception:
                            imx = 0.0
                    if k == 'A':
                        raw = 0.55 * z + 0.25 * imb + 0.45 * imx
                    elif k == 'IDX':
                        raw = 0.6 * z - 0.25 * arb - 0.1 * imb
                    else:
                        raw = 0.65 * z + 0.3 * imb + 0.25 * imx
                        if k in ('B', 'C'):
                            # basket hedge against IDX dislocation: if IDX rich, support components
                            raw = raw + 0.15 * arb
                    if raw != raw:
                        raw = 0.0
                    if raw > 1.0:
                        raw = 1.0
                    if raw < -1.0:
                        raw = -1.0
                    # deadzone to cut turnover
                    if abs(raw) < 0.25:
                        raw = 0.0
            p = prev.get(k, 0.0)
            tgt = 0.65 * p + 0.35 * raw
            if tgt > 1.0:
                tgt = 1.0
            if tgt < -1.0:
                tgt = -1.0
            if abs(tgt) < 0.08:
                tgt = 0.0
            out[k] = float(tgt)
        except Exception:
            continue
    # avoid fee venues: keep flat
    for kx in ('A.X', 'B.X', 'C.X'):
        try:
            p = prev.get(kx, 0.0)
            t = 0.65 * p
            if abs(t) < 0.08:
                t = 0.0
            out[kx] = float(t)
        except Exception:
            out[kx] = 0.0
    st['p'] = dict(out)
    return out

def signal(obs):
    st = obs.state
    prev = st.get('p', {})
    out = {}
    try:
        ab = obs.last('A', 'bid'); aa = obs.last('A', 'ask')
        bb = obs.last('B', 'bid'); ba = obs.last('B', 'ask')
        cb = obs.last('C', 'bid'); ca = obs.last('C', 'ask')
        ib = obs.last('IDX', 'bid'); ia = obs.last('IDX', 'ask')
        vals = (ab, aa, bb, ba, cb, ca, ib, ia)
        ok = True
        for v in vals:
            if v != v or v <= 0:
                ok = False
                break
        if not ok:
            raise ValueError('nan book')
        bask_ask = 0.3333 * aa + 0.6667 * ba + 0.1667 * ca
        bask_bid = 0.3333 * ab + 0.6667 * bb + 0.1667 * cb
        p_sell = ib - bask_ask
        p_buy = bask_bid - ia
    except Exception:
        # keep previous targets on bad data
        return dict(prev) if prev else {}
    # hysteresis thresholds (cents): enter when clearly profitable, exit near zero
    ENTER = 2.0
    EXIT = -4.0
    cur = st.get('dir', 0)
    if cur == 0:
        if p_sell > ENTER:
            cur = -1
        elif p_buy > ENTER:
            cur = 1
    elif cur == -1:
        # short IDX / long basket; exit when edge gone (p_sell back below EXIT) or other side appears
        if p_buy > ENTER:
            cur = 1
        elif p_sell < EXIT:
            cur = 0
    else:
        if p_sell > ENTER:
            cur = -1
        elif p_buy < EXIT:
            cur = 0
    st['dir'] = cur
