def signal(obs):
    # trade A.X based on imbalance momentum
    asset = 'A.X'
    # get recent imbalance
    imb = obs.hist(asset, 'imbalance', 20)
    if len(imb) < 20:
        return {}
    # use latest imbalance
    cur_imb = imb[-1]
    if np.isnan(cur_imb):
        return {}
    # thresholds
    # scale position by imbalance
    # simple: target = sign(imb) * min(1, abs(imb)*2)
    # but we can only target [-1,1]
    scale = min(1.0, abs(cur_imb))
    target = np.sign(cur_imb) * scale
    # require strong signal
    if abs(cur_imb) < 0.2:
        return {}
    return {asset: float(target)}

