result = {}
for asset in ['A','B','C','IDX','A.X','B.X','C.X']:
    mid = H[asset]['mid']
    ret = np.diff(mid)/mid[:-1]
    # lag 1 autocorrelation
    if len(ret) > 1:
        corr = np.corrcoef(ret[1:], ret[:-1])[0,1]
        result[asset+'_ret_autocorr1'] = float(corr)
    # lag 10
