            continue
        if np.isnan(m[-1]) or np.isnan(m[0]):
            continue
        past=m[-1]-m[-50]
        diffs=np.diff(m[-50:])
        vol=np.nanstd(diffs)
        if vol==0 or np.isnan(vol):
            continue
        vol50=vol*np.sqrt(50)
        if vol50==0:
            continue
        score=past/vol50
        prev=st['ema'].get(asset, score)
        ema=0.9*prev+0.1*score
        st['ema'][asset]=ema
        sig=np.tanh(ema*1.2)
        if abs(sig)<0.2:
            sig=0
        else:
            # keep scale
            sig=sig
        targets[asset]=float(np.clip(sig*0.8,-1,1))
    return targets

