        if x == x:  # not NaN
            sv_sum += x
            cnt += 1
    if cnt < 5:
        return {}
    prev = s.get('tar', 0)
    tar = prev
    # entry requires both momentum and flow agreement
    if mom > 10 and sv_sum > 2:
        tar = 1
    elif mom < -10 and sv_sum < -2:
        tar = -1
    else:
        # hysteresis exit
        if prev == 1:
            if mom < 3 or sv_sum < -1:
                # if strong opposite signal, flip directly
                if mom < -10 and sv_sum < -2:
                    tar = -1
                else:
                    tar = 0
        elif prev == -1:
            if mom > -3 or sv_sum > 1:
                if mom > 10 and sv_sum > 2:
                    tar = 1
                else:
                    tar = 0
        else:
            tar = 0
            # allow entry already handled, else stay flat
            if mom > 10 and sv_sum > 2:
                tar = 1
            elif mom < -10 and sv_sum < -2:
                tar = -1
    s['tar'] = tar
    if tar == 0:
        return {'C': 0.0}
    return {'C': float(tar)}

