import math
res = {}
for asset in ['A','C','IDX','B']:
    m = H[asset]['mid']
    # compute 60-step momentum IC with 50-step fwd
    n = len(m)
    mom = [0.0]*n
    for i in range(60, n-50):
        if m[i]==m[i] and m[i-60]==m[i-60]:
            mom[i]=m[i]-m[i-60]
    # correlation quick
    xs=[]; ys=[]
    for i in range(60,n-50):
        if m[i]==m[i] and m[i+50]==m[i+50]:
            xs.append(mom[i]); ys.append(m[i+50]-m[i])
    # pearson
    def pear(x,y):
        nx=len(x)
        mx=sum(x)/nx; my=sum(y)/nx
        num=sum((a-mx)*(b-my) for a,b in zip(x,y))
        dx=sum((a-mx)**2 for a in x); dy=sum((b-my)**2 for b in y)
        return num/((dx*dy)**0.5+1e-9)
    # also hit rate sign
    hit=sum(1 for a,b in zip(xs,ys) if (a>0 and b>0) or (a<0 and b<0))/max(1,len(xs))
    res[asset]=[round(pear(xs,ys),4), round(hit,4), round(float(sum(ys)/len(ys)),3)]
result=res

