def signal(obs):
    # cross-exchange mean reversion for A,B,C
    targets = {}
    for a in ['A','B','C']:
        ax = a+'.X'
        mid1 = obs.last(a,'mid')
        mid2 = obs.last(ax,'mid')
        # get recent diff
        # Use state to keep history of diff
        if not hasattr(obs.state, 'history'):
            obs.state.history = {}
        key = a+'_diff'
        hist = obs.state.history.get(key, [])
        diff = mid1 - mid2
        hist.append(diff)
        maxlen = 100
        if len(hist) > maxlen:
            hist = hist[-maxlen:]
        obs.state.history[key] = hist
        if len(hist) >= 20:
            mean = sum(hist)/len(hist)
            # simple z-score with rolling std
            arr = np.array(hist)
            std = np.std(arr)
            if std > 0:
                z = (diff - mean)/std
                # trade towards mean
                if abs(z) > 1.5:
                    # go long cheaper, short expensive
                    # if mid1>mid2, short 1 long 2
                    if diff > 0:
                        targets[a] = -0.5
                        targets[ax] = 0.5
                    else:
                        targets[a] = 0.5
                        targets[ax] = -0.5
                else:
                    targets[a] = 0.0
                    targets[ax] = 0.0
            else:
                targets[a] = 0.0
                targets[ax] = 0.0
        else:
            targets[a] = 0.0
            targets[ax] = 0.0
    return targets

