def rolling_sum(x,n):
    y=np.full_like(x, np.nan)
    cs=np.cumsum(np.nan_to_num(x, nan=0.0))
    y[n-1:]=cs[n-1:]
    if n>1:
        y[n:] -= cs[:-n]
    return y
