def est_pnl(asset, horizon, th):
    mid=H[asset]['mid']
    sig=np.full_like(mid, np.nan)
    sig[horizon:]=mid[horizon:]-mid[:-horizon]
    pos=np.zeros_like(mid, dtype=float)
    pos[sig>th]=1
    pos[sig<-th]=-1
    fwd10=np.full_like(mid, np.nan)
    fwd10[:-10]=mid[10:]-mid[:-10]
    idx=np.arange(0,n,10)
    pnl_res=0
    pnl_hold=0
    for t in idx:
        if t>=n-10:
            break
        if not np.isfinite(pos[t]) or not np.isfinite(fwd10[t]):
            continue
        if t < cut:
            pnl_res += pos[t]*fwd10[t]
        else:
            pnl_hold += pos[t]*fwd10[t]
    return {'pnl_res':float(pnl_res),'pnl_hold':float(pnl_hold)}
