def pnl_late(assets, th_map, start_offset=750):
    # start_offset = steps from end to simulate (750)
    res={}
    n = len(H['A']['mid'])
    start = n - start_offset
    end = n
    # simulate hysteresis positions
    pos={}
    for a in assets:
        pos[a]=0
    total=0
    # track position history for IC
    pos_hist=[]
    # need mid histories
    for i in range(start, end):
        # update signals at each step? actual signal every 10 steps but approximate every step
        for a in assets:
            if i>=51:
                a_mid=H[a]['mid'][i]
                b_mid=H[a]['mid'][i-50]
                if np.isfinite(a_mid) and np.isfinite(b_mid):
                    mom=a_mid-b_mid
                    th=th_map[a]
                    if mom>th:
                        pos[a]=1
                    elif mom<-th:
                        pos[a]=-1
                    # else keep
        # pnl from moves: sum pos * price change next step? approximate
        if i < end-1:
            step_pnl=0
            for a in assets:
                if np.isfinite(H[a]['mid'][i+1]) and np.isfinite(H[a]['mid'][i]):
                    step_pnl += pos[a]*15*(H[a]['mid'][i+1]-H[a]['mid'][i]) # 15 lots per unit
            total += step_pnl
        pos_hist.append(sum(pos.values()))
    # IC: correlation of summed signal vs forward 50 ret sum?
    # compute mom signal aggregate vs future 50 ret
    # simplified: avg position vs fwd ret
    xs=[]
    ys=[]
    # recompute pos at each i for xs
    pos2={}
    for a in assets:
        pos2[a]=0
    for i in range(start, end-50):
        for a in assets:
            if i>=51:
                a_mid=H[a]['mid'][i]
                b_mid=H[a]['mid'][i-50]
                if np.isfinite(a_mid) and np.isfinite(b_mid):
                    mom=a_mid-b_mid
                    th=th_map[a]
                    if mom>th:
                        pos2[a]=1
                    elif mom<-th:
                        pos2[a]=-1
        agg_pos=sum(pos2[a] for a in assets)
        # future 50 ret aggregated
        fwd=0
        ok=True
        for a in assets:
            if np.isfinite(H[a]['mid'][i+50]) and np.isfinite(H[a]['mid'][i]):
                fwd += H[a]['mid'][i+50]-H[a]['mid'][i]
            else:
                ok=False
        if ok:
            xs.append(agg_pos)
            ys.append(fwd)
    if len(xs)>20:
        cc=np.corrcoef(np.array(xs), np.array(ys))[0,1]
    else:
        cc=np.nan
    return total, cc

