def mycorr2(xs,ys):
  fx=[]; fy=[]
  for i in range(len(xs)):
    a=xs[i]; b=ys[i]
    if a==a and b==b:
      fx.append(a); fy.append(b)
  nn=len(fx)
  if nn<100:
    return 0.0
  mx=sum(fx)/nn; my=sum(fy)/nn
  num=0.0; dx=0.0; dy=0.0
  for i in range(nn):
    ddx=fx[i]-mx; ddy=fy[i]-my
    num+=ddx*ddy; dx+=ddx*ddx; dy+=ddy*ddy
  return num/((dx*dy)**0.5) if dx>0 and dy>0 else 0.0
