def signal(obs):
    st=obs.state
    targets={}
    for pfx in ['A','B','C']:
        m1=obs.hist(pfx,'mid',120)
        m2=obs.hist(pfx+'.X','mid',120)
        if m1 is None or m2 is None or len(m1)<60 or len(m2)<60:
            continue
        if np.isnan(m1[-1]) or np.isnan(m2[-1]):
            continue
        spread=m1[-1]-m2[-1]
        s_hist=m1-m2
        vol=np.nanstd(s_hist[-60:])
        if not np.isfinite(vol) or vol<1e-9:
            continue
        mean=np.nanmean(s_hist[-120:])
        if not np.isfinite(mean):
            mean=0
        z=(spread-mean)/vol
        if abs(z)<0.7:
            z=z*0.5
        sig=np.tanh(z*0.9)
        targets[pfx]=float(np.clip(-sig,-1,1))
        targets[pfx+'.X']=float(np.clip(sig,-1,1))
    try:
        mA=obs.last('A','mid'); mAX=obs.last('A.X','mid')
        mB=obs.last('B','mid'); mBX=obs.last('B.X','mid')
        mC=obs.last('C','mid'); mCX=obs.last('C.X','mid')
        mIDX=obs.last('IDX','mid')
        if np.isfinite(mA) and np.isfinite(mAX):
            fA=(mA+mAX)/2
        else:
            fA=mA if np.isfinite(mA) else mAX
        if np.isfinite(mB) and np.isfinite(mBX):
            fB=(mB+mBX)/2
        else:
            fB=mB if np.isfinite(mB) else mBX
        if np.isfinite(mC) and np.isfinite(mCX):
            fC=(mC+mCX)/2
        else:
            fC=mC if np.isfinite(mC) else mCX
        if all(np.isfinite(x) for x in [fA,fB,fC,mIDX]):
            basket=0.3333*fA+0.6667*fB+0.1667*fC
            mis=mIDX-basket
            hA=obs.hist('A','mid',100); hAX=obs.hist('A.X','mid',100)
            hB=obs.hist('B','mid',100); hBX=obs.hist('B.X','mid',100)
            hC=obs.hist('C','mid',100); hCX=obs.hist('C.X','mid',100)
            hIDX=obs.hist('IDX','mid',100)
            if hA is not None and len(hA)>=80:
                fAh=(hA+hAX)/2; fBh=(hB+hBX)/2; fCh=(hC+hCX)/2
                bask_hist=0.3333*fAh+0.6667*fBh+0.1667*fCh
                mis_hist=hIDX - bask_hist
                vol=np.nanstd(mis_hist[-60:])
                if np.isfinite(vol) and vol>5:
                    z=mis/vol
                    if abs(z)<0.6:
                        z=z*0.3
                    sig=np.tanh(z*0.7)*0.8
                    curIDX=targets.get('IDX',0)
                    targets['IDX']=float(np.clip(curIDX - sig, -1, 1))
                    for pfx,w in [('A',0.3333),('B',0.6667),('C',0.1667)]:
                        add=sig*w*0.9
                        for leg in [pfx, pfx+'.X']:
                            cur=targets.get(leg,0)
                            targets[leg]=float(np.clip(cur+add,-1,1))
    except:
        pass
    return targets

