def signal(obs):
    out = {}
    # explicit flatten IDX to stop stuck short drag unless index arb triggers (added below)
    # dual-listing reversion with deadband
    pairs = (('A','A.X',10.0),('B','B.X',10.0),('C','C.X',15.0))
    for a, ax, thr in pairs:
        try:
            pa = obs.last(a,'mid')
            px = obs.last(ax,'mid')
        except:
            continue
        if pa!=pa or px!=px:
            continue
        sp = pa - px
        if sp > thr:
            out[a] = -1.0
            out[ax] = 1.0
        elif sp < -thr:
            out[a] = 1.0
            out[ax] = -1.0
        else:
            out[a] = 0.0
            out[ax] = 0.0
    # index arb: IDX vs basket(A,B,C cheap legs)
    try:
        ma = obs.last('A','mid'); mb = obs.last('B','mid'); mc = obs.last('C','mid'); mi = obs.last('IDX','mid')
        if ma==ma and mb==mb and mc==mc and mi==mi:
            basket = 0.3333*ma+0.6667*mb+0.1667*mc
            dev = mi - basket
            thrx = 35.0
            if dev > thrx:
                out['IDX'] = -1.0
                # hedge long basket proportionally (override pair signals for A,B,C? blend: take index side if stronger)
                # only apply if pair signals flat to avoid conflict
                if out.get('A',0.0)==0.0:
                    out['A'] = 0.33
                if out.get('B',0.0)==0.0:
                    out['B'] = 0.67
                if out.get('C',0.0)==0.0:
                    out['C'] = 0.17
            elif dev < -thrx:
                out['IDX'] = 1.0
                if out.get('A',0.0)==0.0:
                    out['A'] = -0.33
                if out.get('B',0.0)==0.0:
                    out['B'] = -0.67
                if out.get('C',0.0)==0.0:
                    out['C'] = -0.17
            else:
                # if no index signal, flatten IDX (kill stuck short)
                out['IDX'] = 0.0
        else:
            out['IDX'] = 0.0
    except:
        pass
    return out

