def lag_corr(a,b,lag):
    # corr a[t] vs b[t+lag]
    n = min(len(a), len(b))
    if lag>=0:
        x = a[:n-lag]
        y = b[lag:n+lag] if False else b[lag:n+lag]
        # Actually we want a[t] vs b[t+lag]
        x = a[:n-lag]
        y = b[lag:n]
    else:
        lag = -lag
        x = a[lag:n]
        y = b[:n-lag]
    mask = ~np.isnan(x) & ~np.isnan(y)
    if np.sum(mask)<10:
        return float('nan')
    return float(np.corrcoef(x[mask], y[mask])[0,1])

