    for asset,(lag,thr) in configs.items():
        m1=obs.hist(asset,'mid',lag+1)
        m2=obs.hist(asset+'.X','mid',lag+1)
        if len(m1)<lag+1 or len(m2)<lag+1:
            prev=obs.state.get(asset,0)
            out[asset]=prev
            continue
        a1=m1[-1]; b1=m1[0]; a2=m2[-1]; b2=m2[0]
        if not (np.isfinite(a1) and np.isfinite(b1) and np.isfinite(a2) and np.isfinite(b2)):
            if np.isfinite(a1) and np.isfinite(b1):
                mom=a1-b1
            elif np.isfinite(a2) and np.isfinite(b2):
                mom=a2-b2
            else:
                prev=obs.state.get(asset,0)
                out[asset]=prev
                continue
        else:
            mom=(a1-b1 + a2-b2)/2.0
        prev=obs.state.get(asset,0)
        if mom>thr:
            cur=1
        elif mom < -thr:
            cur=-1
        else:
            cur=prev
        out[asset]=cur
        obs.state[asset]=cur
        out[asset+'.X']=0
    out['IDX']=0
