# test mean reversion vs momentum per asset: corr of past k ret with future 50 ret
import math
res={}
for asset in ['A','B','C','IDX','A.X','B.X','C.X']:
    m=H[asset]['mid']
    for look in [10,30,60]:
        xs=[]; ys=[]
        for i in range(look, len(m)-50, 5):
            if m[i]==m[i] and m[i-look]==m[i-look] and m[i+50]==m[i+50]:
                xs.append(m[i]-m[i-look]); ys.append(m[i+50]-m[i])
        mx=sum(xs)/len(xs); my=sum(ys)/len(ys)
        cov=sum((xs[i]-mx)*(ys[i]-my) for i in range(len(xs)))/len(xs)
        vx=sum((v-mx)**2 for v in xs)/len(xs); vy=sum((v-my)**2 for v in ys)/len(ys)
        corr=cov/math.sqrt(vx*vy) if vx>0 and vy>0 else 0
        res[asset+'_look'+str(look)]=round(corr,4)
result=res

